}

function ensurePrefabCandidates(candidates, needed) {
  const seen = new Set(candidates.map((c) => `${c.chunkX},${c.chunkY}`));
  const fallback = [
    { chunkX: 1, chunkY: 0 },
    { chunkX: -1, chunkY: 0 },
    { chunkX: 0, chunkY: 1 },
    { chunkX: 0, chunkY: -1 },
    { chunkX: 2, chunkY: 0 },
    { chunkX: -2, chunkY: 0 },
    { chunkX: 0, chunkY: 2 },
    { chunkX: 0, chunkY: -2 },
