  const raw = payload?.sound || payload?.kind || payload?.effect || payload?.status || payload?.type || "";
  const key = String(raw || "").toLowerCase();
  return STATUS_SOUND_BY_KIND[key] || null;
}

export function resolveAudioPlayKey(payload) {
