function nextUnit(world) {
  const rand = world?.rand;
  if (typeof rand !== "function") return 0;
  const n = Number(rand.call(world));
  if (!(n > 0)) return 0;
  if (n >= 1) return 1 - Number.EPSILON;
  return n;
}

